js常用算法面试题收集1.统计一个字符出现的最高频率？let str = &#39;asdfghjklaqwertyuiopiaia&#39;;
function statistics(str)&#123;
  const strArr = [...str]
  let obj = &#123;&#125;
  // 统计字符数
  strArr.forEach((i) =&gt;&#123;
    obj[i] = obj[i] == undefined ? 0 :  ++obj[i]
  &#125;)
  // 求最大值
  return Object.keys(obj)
    .sort((i, r) =&gt; obj[r] - obj[i])[0] //降序排列
&#125;
