6、冒泡排序function sort(nums) &#123;
  const n = nums.length

  // 从第一位，循环 n - 1 轮，因为最后一位不用排
  for(let i = 0; i &lt; n - 1; i++) &#123;
    // 每次交换 n - 1 - i 次，因为最后一位不用交换，且每轮排好 1 位数字
    for(let j = 0; j &lt; n - 1 - i; j++) &#123;
      if(nums[j] &gt; nums[j + 1]) &#123;
        swap(nums, j, j + 1)
      &#125;
    &#125;
  &#125;

  return nums
&#125;

function swap(arr, i, j) &#123;
  const temp = arr[i]
  arr[i] = arr[j]
  arr[j] = temp
&#125;

console.log(sort([4,3,1,8,5,2]))
7、分割数组题目：给一个形如[&#39;&#39;, 1, 2, &#39;&#39;, &#39;&#39;, 6, 7, 8]的数组，里面需要分割成[[1,2], [6,7,8]]的形式
// 分割&#39; &#39;,双指针法
function separate(arr) &#123;
  let pre = 0 //前节点
  let cur = 0 // 当前节点
  let res = []
  let _arr = [...arr.slice(0), &#39;&#39;] //加入一个&#39;&#39;,作为结尾，兼容结尾为数字的情况

  while(cur &lt; _arr.length) &#123;
    // 前后节点一致的情况，遇到&#39;&#39;跳过
    if(_arr[pre] === &#39;&#39; &amp;&amp; _arr[cur] === &#39;&#39;) &#123; 
      pre++
      cur++
      continue
    &#125;
  // 前后节点不一致的情况一，都不为空串，只移动cur，相当于记录pre
    if(_arr[pre] !== &#39;&#39; &amp;&amp; _arr[cur] !== &#39;&#39;) &#123;
      cur++
      continue
    &#125;
    // 前后节点不一致的情况二，cur遇到空串，表示到了分割点，加入区间[)到数组
    if(_arr[pre] !== &#39;&#39; &amp;&amp; _arr[cur] === &quot;&quot;) &#123;
      res.push(_arr.slice(pre, cur))
      cur++
      pre = cur
    &#125;
  &#125;

  return res
&#125;

console.log(separate([&#39;&#39;, 1, 2, &#39;&#39;, &#39;&#39;, 6, 7, 8]))
console.log(separate([0, 1, 2, &#39;&#39;, &#39;&#39;, 6, 7, &#39;&#39;]))

