// 方法一，理解简单，但是 slice 会产生额外的空间
function sort(nums) &#123;
  const n = nums.length

  if(n &lt; 2) return nums

  // 注意：此处可以用 n/2 表示 mid，是因为 sort 在 slice 中需要判断的区间是左闭右开的 [ ) ，截取完成的数组需要从 0 ~ n
  const mid = Math.floor(n/2)
  // 分治
  return merge(sort(nums.slice(0, mid)), sort(nums.slice(mid)))
&#125;


// 方法二，直接用下标，不使用额外空间
function sort1(nums, l = 0, r = nums.length - 1) &#123;
  if(l &gt;= r) return [nums[l]]

  // 注意：此处 r = nums.length - 1, 是因为在 sort1 中需要判断的区间是左闭右闭的 [ ]
  const mid = Math.floor((l + r)/2)

  return merge(sort1(nums, l, mid), sort1(nums, mid + 1, r))
&#125;

// 合并数组，使得两个数组有序，上面两种方法可以共用
function merge(l, r) &#123;
  let i = j = 0, newArr = []

  while(l[i] &amp;&amp; r[j]) &#123;
    if(l[i] &lt; r[j]) &#123;
      newArr.push(l[i++])
    &#125;else &#123;
      newArr.push(r[j++])
    &#125;
  &#125;

  if(l[i]) newArr = [...newArr, ...l.slice(i)]

  if(r[j]) newArr = [...newArr, ...r.slice(j)]


  return newArr
&#125;


